/**
 * Small client-side CSV writer for reports built in the browser (e.g. GDTF
 * import results). Data-list exports are generated by the backend instead
 * (see dataExport.ts).
 */

export type CsvCell = string | number | boolean | null | undefined;

/** Characters that make spreadsheet apps treat a cell as a formula. */
const FORMULA_PREFIX = /^[=+\-@\t\r]/;

/**
 * Escape one CSV cell (RFC 4180): quote it when it contains a comma, quote
 * or line break, doubling inner quotes. Text that a spreadsheet would run
 * as a formula (`=`, `+`, `-`, `@`, tab, CR) is prefixed with `'` so file
 * names and messages from imported files stay plain text. Numbers and
 * booleans are written as-is; null / undefined become an empty cell.
 */
export function escapeCsvCell(value: CsvCell): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  let text = value;
  if (FORMULA_PREFIX.test(text)) {
    text = `'${text}`;
  }
  if (/[",\r\n]/.test(text)) {
    return `"${text.replace(/"/g, '""')}"`;
  }
  return text;
}

/** Build CSV text (CRLF line endings) from a header row and data rows. */
export function toCsv(header: ReadonlyArray<string>, rows: ReadonlyArray<ReadonlyArray<CsvCell>>): string {
  return [header, ...rows].map((row) => row.map(escapeCsvCell).join(',')).join('\r\n') + '\r\n';
}
